export class ClientesComponent implements OnInit {
  clients:  ApiClient[] = [];
  selected: ApiClient | null = null;
  loading  = true;
  search   = '';
  page     = 1;
  pageSize = 10;

  constructor(private api: ApiService) {}

  async ngOnInit() {
    try {
      const res = await firstValueFrom(this.api.get<{ clients: ApiClient[] }>('/clients'));
      this.clients = res.clients;
    } catch (err) {
      console.error('[CLIENTES]', err);
    } finally {
      this.loading = false;
    }
  }

  get filteredClients(): ApiClient[] {
    const q = this.search.toLowerCase().trim();
    const list = q
      ? this.clients.filter(c =>
          c.name.toLowerCase().includes(q) ||
          (c.phone && c.phone.includes(q))
        )
      : this.clients;
    return list;
  }

  get pagedClients(): ApiClient[] {
    const start = (this.page - 1) * this.pageSize;
    return this.filteredClients.slice(start, start + this.pageSize);
  }

  get totalPages(): number {
    return Math.ceil(this.filteredClients.length / this.pageSize);
  }

  get pageNumbers(): number[] {
    const total = this.totalPages;
    const cur   = this.page;
    // Mostra no máximo 5 botões centrados na página atual
    let start = Math.max(1, cur - 2);
    let end   = Math.min(total, start + 4);
    start     = Math.max(1, end - 4);
    return Array.from({ length: end - start + 1 }, (_, i) => start + i);
  }

  goToPage(p: number): void {
    if (p < 1 || p > this.totalPages) return;
    this.page = p;
    this.selected = null;
  }

  onSearchChange(): void {
    this.page = 1;      // volta para a primeira página ao buscar
    this.selected = null;
  }

  min(a: number, b: number): number { return Math.min(a, b); }

  getSportIcon(sport: string): string {
    if (sport.includes('tennis'))  return 'sports_tennis';
    if (sport.includes('futev'))   return 'sports_volleyball';
    if (sport.includes('vôlei'))   return 'sports_volleyball';
    if (sport.includes('futebol')) return 'sports_soccer';
    return 'sports';
  }

  getSportColor(sport: string): string {
    if (sport.includes('tennis'))  return 'hsl(38,92%,50%)';
    if (sport.includes('futev'))   return 'hsl(199,89%,48%)';
    if (sport.includes('vôlei'))   return 'hsl(262,80%,60%)';
    if (sport.includes('futebol')) return 'hsl(142,70%,40%)';
    return 'hsl(152,69%,40%)';
  }

  getSportBg(sport: string): string {
    if (sport.includes('tennis'))  return 'hsl(38,92%,50%,0.12)';
    if (sport.includes('futev'))   return 'hsl(199,89%,48%,0.12)';
    if (sport.includes('vôlei'))   return 'hsl(262,80%,60%,0.12)';
    if (sport.includes('futebol')) return 'hsl(142,70%,40%,0.12)';
    return 'hsl(152,69%,40%,0.12)';
  }

  getPaymentClass(s: string): string {
    return s === 'pago' ? 'badge-primary' : s === 'pendente' ? 'badge-accent' : 'badge-muted';
  }
}

import { Injectable, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { ApiService } from './api.service';
import { Court } from '../models/models';

/** Formato retornado pela API */
export interface ApiCourt {
  id: string;
  name: string;
  sport_type: string;
  status: 'DISPONIVEL' | 'BLOQUEADA';
  hourly_rate: number;
  mensalista_rate?: number | null;
  description?: string | null;
}

/** Converte o status do banco (uppercase) para o formato do front */
function fromApi(c: ApiCourt): Court {
  return {
    id:              c.id,
    name:            c.name,
    sport_type:      c.sport_type as Court['sport_type'],
    status:          c.status === 'DISPONIVEL' ? 'disponível' : 'bloqueada',
    hourly_rate:     c.hourly_rate,
    mensalista_rate: c.mensalista_rate ?? null,
    description:     c.description ?? undefined,
  };
}

/** Converte o status do front para o enum do banco */
function toApiStatus(s: string): 'DISPONIVEL' | 'BLOQUEADA' {
  return s === 'disponível' ? 'DISPONIVEL' : 'BLOQUEADA';
}

export interface CourtFormData {
  name: string;
  sport_type: string;
  status: string;
  hourly_rate: number;
  mensalista_rate?: number | null;
  description?: string;
}

@Injectable({ providedIn: 'root' })
export class CourtService {
  private _courts  = signal<Court[]>([]);
  private _loading = signal(false);
  private _saving  = signal(false);
  private _error   = signal<string | null>(null);

  readonly courts  = this._courts.asReadonly();
  readonly loading = this._loading.asReadonly();
  readonly saving  = this._saving.asReadonly();
  readonly error   = this._error.asReadonly();

  constructor(private api: ApiService) {}

  /** Popula as quadras a partir da resposta embutida no estabelecimento */
  seed(rawCourts: ApiCourt[]): void {
    this._courts.set(rawCourts.map(fromApi));
    this._error.set(null);
  }

  async load(): Promise<void> {
    this._loading.set(true);
    this._error.set(null);
    try {
      const res = await firstValueFrom(
        this.api.get<{ courts: ApiCourt[] }>('/courts')
      );
      this._courts.set(res.courts.map(fromApi));
    } catch (e: any) {
      if (e?.status === 404) {
        this._courts.set([]);
      } else {
        this._error.set('Erro ao carregar quadras');
        console.error('[CourtService] load error', e);
      }
    } finally {
      this._loading.set(false);
    }
  }

  async create(data: CourtFormData): Promise<Court> {
    this._saving.set(true);
    try {
      const res = await firstValueFrom(
        this.api.post<{ court: ApiCourt }>('/courts', {
          name:            data.name,
          sport_type:      data.sport_type,
          hourly_rate:     data.hourly_rate,
          mensalista_rate: data.mensalista_rate ?? null,
          status:          toApiStatus(data.status),
          description:     data.description || undefined,
        })
      );
      const court = fromApi(res.court);
      this._courts.update(cs => [...cs, court]);
      return court;
    } finally {
      this._saving.set(false);
    }
  }

  async update(id: string, data: Partial<CourtFormData>): Promise<Court> {
    this._saving.set(true);
    try {
      const body: Record<string, unknown> = { ...data };
      if (data.status !== undefined) {
        body['status'] = toApiStatus(data.status);
      }
      const res = await firstValueFrom(
        this.api.patch<{ court: ApiCourt }>(`/courts/${id}`, body)
      );
      const court = fromApi(res.court);
      this._courts.update(cs => cs.map(c => c.id === id ? court : c));
      return court;
    } finally {
      this._saving.set(false);
    }
  }

  async remove(id: string): Promise<void> {
    this._saving.set(true);
    try {
      await firstValueFrom(
        this.api.delete<{ message: string }>(`/courts/${id}`)
      );
      this._courts.update(cs => cs.filter(c => c.id !== id));
    } finally {
      this._saving.set(false);
    }
  }
}

