@Injectable({ providedIn: 'root' })
export class FinancialService {
  private _financial = signal<FinancialInfo | null | undefined>(undefined);
  private _loading   = signal(false);
  private _loadError = signal<string | null>(null);

  readonly financial    = this._financial.asReadonly();
  readonly loading      = this._loading.asReadonly();
  readonly loadError    = this._loadError.asReadonly();
  readonly hasFinancial = computed(() => !!this._financial());
  readonly isConfigured = computed(() => {
    const f = this._financial();
    return f !== null && f !== undefined;
  });

  constructor(private api: ApiService) {}

  async load(): Promise<void> {
    this._loading.set(true);
    this._loadError.set(null);
    try {
      const res = await firstValueFrom(
        this.api.get<{ financial: FinancialInfo | null }>('/financial/me')
      );
      this._financial.set(res.financial);
    } catch (err: any) {
      const msg = err?.error?.error || err?.message || `Erro ${err?.status ?? 'desconhecido'}`;
      console.error('[FinancialService] load error:', err);
      this._loadError.set(msg);
      this._financial.set(null);
    } finally {
      this._loading.set(false);
    }
  }

  async save(data: SaveFinancialDto): Promise<{ financial: FinancialInfo }> {
    const res = await firstValueFrom(
      this.api.post<{ financial: FinancialInfo }>('/financial/me', data)
    );
    this._financial.set(res.financial);
    return res;
  }

  async saveBank(data: SaveBankDto): Promise<FinancialInfo> {
    const res = await firstValueFrom(
      this.api.post<{ financial: FinancialInfo }>('/financial/bank-account', data)
    );
    this._financial.set(res.financial);
    return res.financial;
  }

  async getRecipientStatus(): Promise<{ id: string; status: string; name: string } | null> {
    try {
      return await firstValueFrom(
        this.api.get<{ id: string; status: string; name: string }>('/financial/recipient-status')
      );
    } catch {
      return null;
    }
  }

  /**
   * Consulta o status do recebedor silenciosamente (sem loading global).
   * Atualiza o pagarme_status no signal. Retorna true se ficou ativo.
   */
  async pollRecipientStatus(): Promise<boolean> {
    try {
      const result = await firstValueFrom(
        this.api.getSilent<{ id: string; status: string; name: string }>('/financial/recipient-status')
      );
      const current = this._financial();
      if (current && result?.status) {
        this._financial.set({ ...current, pagarme_status: result.status });
      }
      return result?.status === 'active';
    } catch {
      return false;
    }
  }

  async getForm(): Promise<FinancialFormData | null> {
    const res = await firstValueFrom(
      this.api.get<{ form: FinancialFormData | null }>('/financial/me/form')
    );
    return res.form;
  }

  async updateTransferSettings(interval: 'Daily' | 'Weekly' | 'Monthly', day: number): Promise<void> {
    await firstValueFrom(
      this.api.put<{ success: boolean; interval: string; day: number }>('/financial/transfer-settings', { interval, day })
    );
    // Atualiza o signal local sem recarregar tudo
    const current = this._financial();
    if (current) {
      this._financial.set({ ...current, transfer_interval: interval, transfer_day: day });
    }
  }

  reset(): void {
    this._financial.set(undefined);
  }
}

