                              <animateTransform attributeName="transform" type="scale"
                                       values="1;1.18;1"
                                       keyTimes="0;0.38;1"
                                       dur="5s" begin="1.4s" repeatCount="indefinite"
                                       calcMode="spline"
                                       keySplines="0.42 0 0.58 1;0.42 0 0.58 1"/>
                            </path>
