                      <span class="material-icons" style="font-size:1.25rem;color:#4ade80">verified_user</span>
                      <div style="font-family:'Space Grotesk',sans-serif;font-weight:900;font-size:1.7rem;color:#fff;line-height:1">99.9%</div>
