  { key: 'promotions',         label: 'Promoções',          icon: 'local_offer'        },
  { key: 'advanced_reports',   label: 'Rel. Avançados',     icon: 'bar_chart'          },
  { key: 'split_payment',      label: 'Divisão Pagamento',  icon: 'group'              },
