import { Injectable } from '@angular/core';
import { HttpClient, HttpContext, HttpContextToken, HttpParams } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';

/** Token para marcar requisições silenciosas — ignora o loading global */
export const SILENT_REQUEST = new HttpContextToken<boolean>(() => false);

@Injectable({ providedIn: 'root' })
export class ApiService {
  readonly baseUrl = environment.apiUrl;

  constructor(public http: HttpClient) {}

  get<T>(path: string, params?: Record<string, string>): Observable<T> {
    let httpParams = new HttpParams();
    if (params) {
      Object.entries(params).forEach(([k, v]) => { if (v) httpParams = httpParams.set(k, v); });
    }
    return this.http.get<T>(`${this.baseUrl}${path}`, { params: httpParams });
  }

  /** Requisição GET que não dispara o loading global (ex: polling silencioso) */
  getSilent<T>(path: string, params?: Record<string, string>): Observable<T> {
    let httpParams = new HttpParams();
    if (params) {
      Object.entries(params).forEach(([k, v]) => { if (v) httpParams = httpParams.set(k, v); });
    }
    return this.http.get<T>(`${this.baseUrl}${path}`, {
      params:  httpParams,
      context: new HttpContext().set(SILENT_REQUEST, true),
    });
  }

  post<T>(path: string, body: unknown): Observable<T> {
    return this.http.post<T>(`${this.baseUrl}${path}`, body);
  }

  /** POST silencioso — não dispara o loading global */
  postSilent<T>(path: string, body: unknown): Observable<T> {
    return this.http.post<T>(`${this.baseUrl}${path}`, body, {
      context: new HttpContext().set(SILENT_REQUEST, true),
    });
  }

  put<T>(path: string, body: unknown): Observable<T> {
    return this.http.put<T>(`${this.baseUrl}${path}`, body);
  }

  patch<T>(path: string, body: unknown): Observable<T> {
    return this.http.patch<T>(`${this.baseUrl}${path}`, body);
  }

  delete<T>(path: string): Observable<T> {
    return this.http.delete<T>(`${this.baseUrl}${path}`);
  }
}

import { Injectable, signal } from '@angular/core';
import {
  signInWithPopup,
  GoogleAuthProvider,
  signOut,
  onAuthStateChanged,
  signInWithEmailAndPassword,
  createUserWithEmailAndPassword,
  sendPasswordResetEmail,
  updateProfile,
  User
} from 'firebase/auth';
import { firebaseAuth } from '../firebase.config';
import { ProfileService } from './profile.service';

@Injectable({ providedIn: 'root' })
export class AuthService {
  user = signal<User | null>(null);
  loading = signal(true);

  constructor(private profileService: ProfileService) {
    onAuthStateChanged(firebaseAuth, (u) => {
      if (u) {
        this.profileService.init(u.uid);
      } else {
        this.profileService.clear();
      }
      this.user.set(u);
      this.loading.set(false);
    });
  }

  loginWithGoogle() {
    return signInWithPopup(firebaseAuth, new GoogleAuthProvider());
  }

  loginWithEmail(email: string, password: string) {
    return signInWithEmailAndPassword(firebaseAuth, email, password);
  }

  registerWithEmail(name: string, email: string, password: string) {
    return createUserWithEmailAndPassword(firebaseAuth, email, password).then(cred =>
      updateProfile(cred.user, { displayName: name }).then(() => cred)
    );
  }

  resetPassword(email: string) {
    return sendPasswordResetEmail(firebaseAuth, email);
  }

  logout() {
    return signOut(firebaseAuth);
  }

  isLoggedIn(): boolean {
    return !!this.user();
  }
}

