  monthly_income: string;
  professional_occupation: string;
  address: string;
  address_number: string;
  complement: string;
  province: string;
  postal_code: string;
  city: string;
  state: string;
  bank_code: string;
  bank_account_type: string;
  bank_agency: string;
  bank_agency_digit: string;
