/* ── Floating support button ── */
.support-fab {
  position: fixed;
  bottom: 1rem;
  right: 0;
  z-index: 200;
  width: 3.25rem;
  height: 3.25rem;
  border-radius: 50% 0 0 50%;
  background: var(--primary);
  color: white;
  border: none;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: -4px 6px 24px rgba(34,197,94,0.4);
  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s;
}
.support-fab:hover {
  transform: translateY(-2px) scale(1.05);
  box-shadow: -4px 10px 30px rgba(34,197,94,0.5);
}
.support-fab--active {
  background: var(--muted-foreground);
  box-shadow: -4px 4px 16px rgba(0,0,0,0.2);
}

/* ── Support panel ── */
.support-panel {
  position: fixed;
  bottom: 5rem;
  right: 0;
  z-index: 199;
  width: min(22rem, calc(100vw - 2rem));
  max-height: 70vh;
  border-radius: 1.25rem 0 0 1.25rem;
  background: var(--card);
  border: 1px solid var(--border);
  border-right: none;
  box-shadow: -8px 20px 60px rgba(0,0,0,0.18);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transform: scale(0.92) translateY(12px);
  opacity: 0;
  pointer-events: none;
  transition: transform 0.25s cubic-bezier(0.4,0,0.2,1), opacity 0.2s ease;
  transform-origin: bottom right;
}
.support-panel--open {
  transform: scale(1) translateY(0);
  opacity: 1;
  pointer-events: all;
}

.support-panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1rem 0.875rem;
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
  background: linear-gradient(135deg, hsl(152,69%,40%,0.06), transparent);
}
.support-panel__avatar {
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), hsl(152,69%,30%));
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.support-panel__close {
  width: 1.75rem;
  height: 1.75rem;
  border-radius: 50%;
  border: none;
  background: var(--muted);
  color: var(--muted-foreground);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s;
}
.support-panel__close:hover { background: var(--border); }

.support-panel__body {
  flex: 1;
  overflow-y: auto;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.support-msg { display: flex; flex-direction: column; max-width: 85%; }
.support-msg--in  { align-self: flex-start; }
.support-msg--out { align-self: flex-end; align-items: flex-end; }

.support-msg__bubble {
  padding: 0.55rem 0.9rem;
  border-radius: 1rem;
  font-size: 0.82rem;
  line-height: 1.45;
  background: var(--muted);
  color: var(--foreground);
  border-bottom-left-radius: 0.25rem;
}
.support-msg__bubble--out {
  background: var(--primary);
  color: white;
  border-bottom-left-radius: 1rem;
  border-bottom-right-radius: 0.25rem;
}
.support-msg__time {
  font-size: 0.67rem;
  color: var(--muted-foreground);
  margin-top: 0.2rem;
  padding: 0 0.25rem;
}

/* Typing indicator */
.support-typing {
  display: flex !important;
  gap: 0.3rem;
  padding: 0.65rem 0.9rem;
  align-items: center;
}
.support-typing span {
  width: 0.45rem;
  height: 0.45rem;
  border-radius: 50%;
  background: var(--muted-foreground);
  animation: typing-dot 1.2s infinite ease-in-out;
}
.support-typing span:nth-child(2) { animation-delay: 0.2s; }
.support-typing span:nth-child(3) { animation-delay: 0.4s; }
@keyframes typing-dot {
  0%, 60%, 100% { transform: translateY(0); opacity: 0.4; }
  30% { transform: translateY(-4px); opacity: 1; }
}

.support-panel__notice {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.45rem 1rem;
  font-size: 0.7rem;
  color: var(--muted-foreground);
  background: hsl(38,92%,50%,0.07);
  border-top: 1px solid hsl(38,92%,50%,0.15);
  flex-shrink: 0;
}

.support-panel__footer {
  display: flex;
  align-items: flex-end;
  gap: 0.5rem;
  padding: 0.75rem;
  border-top: 1px solid var(--border);
  flex-shrink: 0;
}
.support-panel__input {
  flex: 1;
  resize: none;
  border-radius: 0.75rem;
  border: 1.5px solid var(--border);
  background: var(--background);
  color: var(--foreground);
  padding: 0.55rem 0.75rem;
  font-size: 0.82rem;
  line-height: 1.4;
  max-height: 6rem;
  outline: none;
  transition: border-color 0.15s;
  font-family: inherit;
}
.support-panel__input:focus { border-color: var(--primary); }
.support-panel__input::placeholder { color: var(--muted-foreground); }
.support-panel__send {
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 50%;
  border: none;
  background: var(--primary);
  color: white;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: opacity 0.15s, transform 0.15s;
