.feat-grid-new { display:grid; grid-template-columns:repeat(2,1fr); gap:0.75rem; }
.feat-card-new {
  border-radius:1rem; overflow:hidden; position:relative; aspect-ratio:4/3;
  display:flex; flex-direction:column; justify-content:flex-end; padding:1rem;
  background:linear-gradient(145deg,rgba(13,50,26,0.9),rgba(4,15,9,0.95));
  border:1px solid rgba(34,165,92,0.12); transition:border-color 0.2s,transform 0.2s;
}
.feat-card-new:hover { border-color:rgba(34,165,92,0.35); transform:translateY(-2px); }

/* ── CTA block ──────────────────────────────── */
.cta-block { border-radius:1.5rem; background:linear-gradient(135deg,#1c9e54,#127838); padding:2.5rem; position:relative; overflow:hidden; }
@media (max-width:1023px) { .cta-block { padding:1.75rem 1.5rem; border-radius:1.25rem; } }

/* ── Toggle mensal/anual ────────────────────── */
.billing-toggle {
  display:inline-flex; align-items:center; flex-wrap:wrap; gap:0.25rem;
  background:rgba(255,255,255,0.06); border-radius:2rem;
  padding:0.25rem; margin-bottom:1.25rem;
}
.billing-toggle-btn {
  display:inline-flex; align-items:center; gap:0.4rem;
  padding:0.38rem 1rem; border-radius:2rem; border:none; cursor:pointer;
  font-size:0.8rem; font-weight:600; font-family:'Space Grotesk',sans-serif;
  background:transparent; color:rgba(255,255,255,0.45);
  transition:background 0.2s,color 0.2s;
}
.billing-toggle-btn.active {
  background:rgba(255,255,255,0.14); color:#fff;
}
.billing-toggle-badge {
  display:inline-flex; align-items:center;
  background:rgba(34,165,92,0.22); color:#4ade80;
  font-size:0.62rem; font-weight:800; border-radius:2rem;
  padding:0.1rem 0.45rem; letter-spacing:0.03em; line-height:1.4;
}
.annual-sub {
  font-size:0.65rem; color:rgba(255,255,255,0.38);
  margin:0.15rem 0 0; font-weight:400;
}

/* ── Plan grid (desktop) ─────────────────────── */
.plan-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.9rem;
  align-items: stretch;
}
@media (min-width: 1300px) {
  .plan-grid { grid-template-columns: repeat(4, 1fr); gap: 1rem; }
}

/* ── Skeleton shimmer ───────────────────────── */
.sk-card {
  border-radius: 1.5rem;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.07);
  padding: 2rem 1.75rem;
  display: flex; flex-direction: column; gap: 0.75rem;
  min-height: 380px; overflow: hidden; position: relative;
}
.sk-card--mobile {
  border-radius: 1.25rem;
  padding: 1.25rem;
  min-height: 260px;
  margin-bottom: 1rem;
}
.sk-line {
  border-radius: 0.4rem;
  background: linear-gradient(90deg,
    rgba(255,255,255,0.05) 25%,
    rgba(255,255,255,0.13) 50%,
    rgba(255,255,255,0.05) 75%);
  background-size: 200% 100%;
  animation: sk-shimmer 1.6s ease-in-out infinite;
}
.sk-line--sm  { height: 0.55rem; width: 40%; }
.sk-line--md  { height: 0.75rem; width: 65%; }
.sk-line--lg  { height: 2.8rem;  width: 70%; border-radius: 0.5rem; }
.sk-line--xl  { height: 1rem;    width: 90%; }
.sk-line--full{ height: 0.65rem; width: 100%; }
.sk-btn {
  margin-top: auto;
  height: 2.6rem; border-radius: 0.875rem;
  background: linear-gradient(90deg,
    rgba(255,255,255,0.05) 25%,
    rgba(255,255,255,0.13) 50%,
    rgba(255,255,255,0.05) 75%);
  background-size: 200% 100%;
  animation: sk-shimmer 1.6s ease-in-out infinite;
}
@keyframes sk-shimmer {
  0%   { background-position:  200% 0; }
  100% { background-position: -200% 0; }
}

