/* ── Modal legal ── */
.legal-overlay {
  position: fixed; inset: 0; z-index: 9000;
  background: rgba(0,0,0,0.5);
  backdrop-filter: blur(4px);
  display: flex; align-items: center; justify-content: center;
  animation: fadeIn 0.2s ease;
}
.legal-modal {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 1.25rem;
  width: calc(100% - 2rem); max-width: 560px;
  max-height: 78vh;
  display: flex; flex-direction: column;
  padding: 1.25rem 1.25rem 1.5rem;
  overflow: hidden;
  box-shadow: 0 20px 60px rgba(0,0,0,0.25);
}
.legal-tab {
  flex: 1; background: none; border: none; cursor: pointer;
  padding: 0.6rem 0; font-size: 0.8rem; font-weight: 600;
  color: var(--muted-foreground);
  border-bottom: 2px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}
.legal-tab.active { color: var(--primary); border-bottom-color: var(--primary); }
.legal-body {
  overflow-y: auto; flex: 1; padding-right: 0.25rem;
  scrollbar-width: thin;
  scrollbar-color: var(--border) transparent;
}
.legal-body h2 { font-size: 1rem; font-weight: 700; color: var(--foreground); margin: 0.5rem 0 0.25rem; }
.legal-body h3 { font-size: 0.72rem; font-weight: 700; color: var(--primary); margin: 1rem 0 0.3rem; text-transform: uppercase; letter-spacing: 0.05em; }
.legal-body p, .legal-body li { font-size: 0.78rem; color: var(--muted-foreground); line-height: 1.65; margin: 0 0 0.4rem; }
.legal-body ul { padding-left: 1.1rem; margin: 0.3rem 0 0.6rem; }
.legal-updated { font-size: 0.68rem !important; color: var(--border) !important; }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }

.drag-over {
  border-color: var(--primary) !important;
  background-color: rgba(34,197,94,0.05);
}
.info-label {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  margin-bottom: 0.375rem;
  color: var(--foreground);
  opacity: 0.8;
}
.info-input-wrap {
  position: relative;
}
.info-icon {
  position: absolute;
  left: 0.65rem;
  top: 50%;
  transform: translateY(-50%);
  font-size: 1rem !important;
  color: var(--muted-foreground);
  pointer-events: none;
  z-index: 1;
}
.info-input {
  padding-left: 2.25rem !important;
  background-color: var(--input-bg) !important;
  height: 2.6rem;
}
.hours-block {
  margin-top: 0.5rem;
  padding-top: 1rem;
  border-top: 1px dashed var(--border);
}
.hours-sub-label {
  display: block;
  font-size: 0.7rem;
  font-weight: 600;
  margin-bottom: 0.3rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: var(--muted-foreground);
}
.hours-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.25rem 0.65rem;
  border-radius: 9999px;
  font-size: 0.72rem;
  font-weight: 700;
  background: hsl(152, 69%, 40%, 0.12);
  color: var(--primary);
  border: 1px solid hsl(152, 69%, 40%, 0.25);
}
.timeline-track {
  position: relative;
  height: 14px;
  border-radius: 9999px;
  background: var(--muted);
  margin: 1.4rem 0 0.5rem;
  cursor: default;
  user-select: none;
  -webkit-user-select: none;
}
.timeline-bg {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  border-radius: 9999px 0 0 9999px;
  background: var(--muted);
  pointer-events: none;
}
.timeline-fill {
  position: absolute;
  top: 0;
  bottom: 0;
  border-radius: 0;
  background: linear-gradient(
    90deg,
    hsl(152, 69%, 50%) 0%,
    hsl(152, 69%, 42%) 100%
  );
  box-shadow: 0 2px 10px rgba(34, 197, 94, 0.4);
  transition: left 0.06s ease, width 0.06s ease;
  pointer-events: none;
}
.timeline-fill.dragging {
  transition: none;
}
.timeline-tick {
  position: absolute;
  top: 2px;
  bottom: 2px;
  width: 1.5px;
  background: rgba(255,255,255,0.35);
  transform: translateX(-50%);
  pointer-events: none;
  border-radius: 9999px;
}
.timeline-handle {
  position: absolute;
  top: 50%;
  width: 22px;
  height: 22px;
  border-radius: 9999px;
  background: #fff;
  border: 3px solid var(--primary);
  transform: translate(-50%, -50%);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.18);
  cursor: grab;
  transition: left 0.06s ease, box-shadow 0.15s ease, transform 0.15s ease;
  touch-action: none;
  z-index: 2;
}
.timeline-handle:hover,
.timeline-handle.active {
  box-shadow: 0 0 0 5px hsl(152, 69%, 40%, 0.18), 0 3px 10px rgba(0,0,0,0.2);
  transform: translate(-50%, -50%) scale(1.15);
}
.timeline-handle.active {
  cursor: grabbing;
  transition: none;
}
.handle-tooltip {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  background: var(--foreground);
  color: var(--background, #fff);
  font-size: 0.68rem;
  font-weight: 700;
  padding: 0.2rem 0.45rem;
  border-radius: 0.35rem;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.15s ease;
  box-shadow: 0 2px 6px rgba(0,0,0,0.15);
}
.handle-tooltip::after {
  content: '';
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  border: 4px solid transparent;
  border-top-color: var(--foreground);
}
.timeline-handle:hover .handle-tooltip,
.timeline-handle.active .handle-tooltip {
  opacity: 1;
}
.timeline-labels {
  display: flex;
  justify-content: space-between;
  font-size: 0.65rem;
  font-weight: 600;
  color: var(--muted-foreground);
  letter-spacing: 0.03em;
  padding: 0 4px;
  margin-top: 0.3rem;
}
.hours-summary {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin-top: 0.85rem;
  padding: 0.55rem 0.75rem;
  border-radius: 0.65rem;
  background: var(--muted);
  font-size: 0.75rem;
  color: var(--muted-foreground);
}
.hours-summary strong {
  color: var(--foreground);
  font-weight: 700;
}
/* Toggle switch */
.toggle-btn {
  position: relative;
  width: 44px;
  height: 24px;
  border-radius: 9999px;
  background: var(--muted);
  border: none;
  cursor: pointer;
  transition: background 0.2s;
  padding: 0;
  flex-shrink: 0;
}
.toggle-btn.toggle-on {
  background: var(--primary);
}
.toggle-knob {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 18px;
  height: 18px;
  border-radius: 9999px;
  background: #fff;
  box-shadow: 0 1px 4px rgba(0,0,0,0.2);
  transition: transform 0.2s;
}
.toggle-on .toggle-knob {
  transform: translateX(20px);
}

