src/app/interceptors/loading.interceptor.defaultValue:
(req, next) => {
  // Requisições silenciosas (ex: polling de status) não ativam o loading global
  if (req.context.get(SILENT_REQUEST)) return next(req);

  const loading = inject(LoadingService);
  loading.show();
  return next(req).pipe(finalize(() => loading.hide()));
}

src/app/guards/platform-admin.guard.ts.defaultValue:
() => {
  const auth   = inject(AuthService);
  const router = inject(Router);

  // Aguarda o Firebase terminar de inicializar antes de decidir
  return toObservable(auth.loading).pipe(
    filter(loading => !loading),
    take(1),
    map(() => {
      const user = auth.user();
      if (user?.email === PLATFORM_ADMIN_EMAIL) return true;
      router.navigate(['/']);
      return false;
    }),
  );
}

